func find_first_duplicate (nums []int) int {
	// Write your code here
	if len(nums) == 0 {
		return -1
	}
	for i := 0; i < len(nums); i++ {
		if nums[i] < 0 {
			return -1
		}
	}
	for i := 0; i < len(nums); i++ {
		if nums[i] > len(nums) {
			return -1
		}
	}
	for i := 0; i < len(nums); i++ {
		if nums[i] == i {
			continue
		}
		if nums[i] == nums[nums[i]] {
			return nums[i]
		}
		nums[nums[i]], nums[i] = nums[i], nums[nums[i]]
	}
	return -1
}

