// >>> 2
// >>> get_gcd([1, 2, 3])
// >>> 1
// >>> get_gcd([2, 4, 6, 8])
// >>> 2
func get_gcd (l []int) int {
	if len(l) == 0 {
		return 0
	}
	if len(l) == 1 {
		return l[0]
	}
	if len(l) == 2 {
		return gcd(l[0], l[1])
	}
	return gcd(l[0], get_gcd(l[1:]))
}

func gcd(a, b int) int {
	for b != 0 {
		t := b
		b = a % b
		a = t
	}
	return a
}

