// >>> counting_sort([8, 4, 14, 3, 2, 1])
// >>> [1, 2, 3, 4, 8, 14]
func counting_sort (my_list []int) []int {
	// Write your code here
	max := my_list[0]
	min := my_list[0]
	for i := 0; i < len(my_list); i++ {
		if my_list[i] > max {
			max = my_list[i]
		}
		if my_list[i] < min {
			min = my_list[i]
		}
	}
	count := make([]int, max-min+1)
	for i := 0; i < len(my_list); i++ {
		count[my_list[i]-min]++
	}
	for i := 1; i < len(count); i++ {
		count[i] += count[i-1]
	}
	result := make([]int, len(my_list))
	for i := len(my_list)-1; i >= 0; i-- {
		result[count[my_list[i]-min]-1] = my_list[i]
		count[my_list[i]-min]--
	}
	return result
}

