// Code should be written in Go/Golang
// Write a golang function to find number of integers with odd number of set bits.
// Examples:
// >>> count_With_Odd_SetBits(5)
// >>> 3
// >>> count_With_Odd_SetBits(10)
// >>> 5
// >>> count_With_Odd_SetBits(15)
// >>> 8
func count_With_Odd_SetBits (n int) float64 {
	var count float64
	for i := 1; i <= n; i++ {
		count += float64(popcount(i))
	}
	return count
}

func popcount(x int) int {
	var count int
	for x != 0 {
		count++
		x &= (x - 1)
	}
	return count
}

