// >>> 8
// >>> even_binomial_Coeff_Sum(6)
// >>> 32
// >>> even_binomial_Coeff_Sum(2)
// >>> 2
func even_binomial_Coeff_Sum (n int) int {
	var sum int
	for i := 0; i <= n; i++ {
		if i%2 == 0 {
			sum += binomialCoeff(n, i)
		}
	}
	return sum
}

func binomialCoeff(n, k int) int {
	if k == 0 {
		return 1
	}
	if k > n-k {
		k = n - k
	}
	var result int = 1
	for i := 1; i <= k; i++ {
		result *= n - k + i
		result /= i
	}
	return result
}

