// >>> False
func binary_search (item_list []int, item int) bool {
	var low, high, mid int
	low = 0
	high = len(item_list) - 1
	for low <= high {
		mid = (low + high) / 2
		if item_list[mid] == item {
			return true
		} else if item_list[mid] < item {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	return false
}

