// Write a function to sort a list of elements using radix sort.
// Examples:
// >>> radix_sort([15, 79, 25, 68, 37])
// >>> [15, 25, 37, 68, 79]
// >>> radix_sort([9, 11, 8, 7, 3, 2])
// >>> [2, 3, 7, 8, 9, 11]
// >>> radix_sort([36, 12, 24, 26, 29])
// >>> [12, 24, 26, 29, 36]
func radix_sort (nums []int) []int {
	// Write your code here
	if len(nums) == 0 {
		return nums
	}
	max := nums[0]
	for _, num := range nums {
		if num > max {
			max = num
		}
	}
	for i := 0; i < 10; i++ {
		count := make([]int, 10)
		for _, num := range nums {
			count[num/max%10]++
		}
		for j := 1; j < 10; j++ {
			count[j] += count[j-1]
		}
		sorted := make([]int, len(nums))
		for i := len(nums) - 1; i >= 0; i-- {
			sorted[count[nums[i]/max%10] - 1] = nums[i]
			count[nums[i]/max%10]--
		}
		nums = sorted
		max /= 10
	}
	return nums
}

