// >>> 24
// >>> get_lcm([3, 8, 4, 10, 5])
// >>> 120
func get_lcm (l []int) int {
	var lcm int
	for i := 0; i < len(l); i++ {
		for j := 0; j < len(l); j++ {
			if i != j {
				lcm = lcm * l[i] / gcd(l[i], l[j])
			}
		}
	}
	return lcm
}

func gcd(a, b int) int {
	for b != 0 {
		t := b
		b = a % b
		a = t
	}
	return a
}

